    .macro save_context_registers
    add sp, sp, -(32*4)
#   sw  x0,  (0*4)(sp)   # x0 是 zero, 无需保存
    sw  x1,  (1*4)(sp)
#   sw  x2,  (2*4)(sp)   # x2 是 sp, 如有需要,在宏外面保存
    sw  x3,  (3*4)(sp)
    sw  x4,  (4*4)(sp)
    sw  x5,  (5*4)(sp)
    sw  x6,  (6*4)(sp)
    sw  x7,  (7*4)(sp)
    sw  x8,  (8*4)(sp)
    sw  x9,  (9*4)(sp)
    sw  x10, (10*4)(sp)
    sw  x11, (11*4)(sp)
    sw  x12, (12*4)(sp)
    sw  x13, (13*4)(sp)
    sw  x14, (14*4)(sp)
    sw  x15, (15*4)(sp)
    sw  x16, (16*4)(sp)
    sw  x17, (17*4)(sp)
    sw  x18, (18*4)(sp)
    sw  x19, (19*4)(sp)
    sw  x20, (20*4)(sp)
    sw  x21, (21*4)(sp)
    sw  x22, (22*4)(sp)
    sw  x23, (23*4)(sp)
    sw  x24, (24*4)(sp)
    sw  x25, (25*4)(sp)
    sw  x26, (26*4)(sp)
    sw  x27, (27*4)(sp)
    sw  x28, (28*4)(sp)
    sw  x29, (29*4)(sp)
    sw  x30, (30*4)(sp)
    sw  x31, (31*4)(sp)
    nop                  # 这里加上一个nop 防止sw 之后立马 lw导致cpu卡死的这个问题
    .endm

    .macro restore_context_registers
#   lw  x0,  (0*4)(sp)   # x0 是 zero, 不需要恢复
    lw  x1,  (1*4)(sp)
#   lw  x2,  (2*4)(sp)   # x2 是 sp, 不在宏里面恢复
    lw  x3,  (3*4)(sp)
    lw  x4,  (4*4)(sp)
    lw  x5,  (5*4)(sp)
    lw  x6,  (6*4)(sp)
    lw  x7,  (7*4)(sp)
    lw  x8,  (8*4)(sp)
    lw  x9,  (9*4)(sp)
    lw  x10, (10*4)(sp)
    lw  x11, (11*4)(sp)
    lw  x12, (12*4)(sp)
    lw  x13, (13*4)(sp)
    lw  x14, (14*4)(sp)
    lw  x15, (15*4)(sp)
    lw  x16, (16*4)(sp)
    lw  x17, (17*4)(sp)
    lw  x18, (18*4)(sp)
    lw  x19, (19*4)(sp)
    lw  x20, (20*4)(sp)
    lw  x21, (21*4)(sp)
    lw  x22, (22*4)(sp)
    lw  x23, (23*4)(sp)
    lw  x24, (24*4)(sp)
    lw  x25, (25*4)(sp)
    lw  x26, (26*4)(sp)
    lw  x27, (27*4)(sp)
    lw  x28, (28*4)(sp)
    lw  x29, (29*4)(sp)
    lw  x30, (30*4)(sp)
    lw  x31, (31*4)(sp)
    add sp, sp, (32*4)
    .endm
